def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    components = []

    while unseen:
        start = unseen.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                if (nr, nc) in unseen:
                    unseen.remove((nr, nc))
                    comp.add((nr, nc))
                    q.append((nr, nc))
        components.append(comp)

    if not components:
        return [row[:] for row in grid]

    pattern = max(components, key=len)
    rs = [r for r, c in pattern]
    cs = [c for r, c in pattern]
    ar = (min(rs) + max(rs)) // 2
    ac = (min(cs) + max(cs)) // 2
    offsets = [(r-ar, c-ac, grid[r][c]) for r, c in pattern]

    markers = [next(iter(comp)) for comp in components if comp is not pattern]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr, dc, color in offsets:
            r, c = mr + dr, mc + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out
